// spatialGeometry.ts
export function ribbon(a: Point2, b: Point2, w: number, y: number): number[] {
  const dx = b[0] - a[0], dz = b[1] - a[1], l = Math.hypot(dx, dz) || 1;
  const tx = dx / l * w / 2, tz = dz / l * w / 2, nx = -tz, nz = tx;
  const A: Point2 = [a[0] - tx + nx, a[1] - tz + nz], B: Point2 = [b[0] + tx + nx, b[1] + tz + nz];
  const C: Point2 = [b[0] + tx - nx, b[1] + tz - nz], D: Point2 = [a[0] - tx - nx, a[1] - tz - nz];
  return hullTriangles([D, C, B, A], y); // CCW in, upward out; end caps overlap at joints
}

export function districtRegions(layout: Layout, y: number) {
  const byRoot = new Map<string, Vec3[]>();
  for (const id of layout.units) {
    const r = rootOf(layout, id), p = layout.positions.get(id);
    if (r && p) (byRoot.get(r) ?? byRoot.set(r, []).get(r)!).push(p);
  }
  const key = (p: Point2) => `${Math.round(p[0] * 1e3)},${Math.round(p[1] * 1e3)}`;
  const out = new Map<string, { fill: number[]; outline: [Point2, Point2][] }>();
  for (const [root, cells] of byRoot) {
    const { pitch, phase } = latticeOf(cells, layout.cell); // nearest-neighbour distance; phase 0 or π/6
    const R = pitch / Math.sqrt(3), fill: number[] = [], edges = new Map<string, [Point2, Point2]>();
    for (const c of cells) {
      const v = Array.from({ length: 6 }, (_, i): Point2 => {
        const a = phase + i * Math.PI / 3;
        return [c[0] + Math.sin(a) * R, c[2] + Math.cos(a) * R];
      });
      fill.push(...hullTriangles([...v].reverse(), y));
      v.forEach((p, i) => {
        const q = v[(i + 1) % 6]!, k = [key(p), key(q)].sort().join("|");
        edges.has(k) ? edges.delete(k) : edges.set(k, [p, q]);
      });
    }
    out.set(root, { fill, outline: [...edges.values()] });
  }
  return out;
}

// SpatialGround rails
const gap = Math.min(0.25 * (sector.end - sector.start), 0.35 / sector.radius);
const s = sector.start + gap / 2, e = sector.end - gap / 2;
const fillEnd = s + (e - s) * clamp01(score.readiness);
add(all, cols, arcTriangles(R - w, R + w, s, fillEnd, 0.03), TOKENS.status[score.status]);
add(all, cols, arcTriangles(R - w * 0.3, R + w * 0.3, fillEnd, e, 0.03), trackColor);
for (const q of [0.25, 0.5, 0.75]) {
  const a = s + (e - s) * q, h = 0.03 / R;
  add(all, cols, arcTriangles(R + w, R + w * 2.2, a - h, a + h, 0.03), trackColor);
}

